using System.Collections.Generic; public sealed class AudioRestorationPuzzleController:ValidatedPuzzleController { private readonly List<string> segments=new();protected override void ResetPuzzle()=>segments.Clear();public void SetOrder(IEnumerable<string> ids){segments.Clear();if(ids!=null)segments.AddRange(ids);}public bool Submit(string[] expected){if(expected==null||expected.Length!=segments.Count)return false;for(int i=0;i<expected.Length;i++)if(expected[i]!=segments[i])return false;return CompleteWhen(true,string.Join(",",segments));} }
